INSERT INTO `sys_error` (`id`, `created_at`, `updated_at`, `deleted_at`, `form`, `info`, `level`, `solution`, `status`) VALUES (149, '2026-03-26 22:00:01.382', '2026-03-26 22:00:01.382', NULL, '后端', '更新失败! | 错误: record not found \n 源文件:/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/starNote/note_category.go:288 \n 调用栈：github.com/flipped-aurora/gin-vue-admin/server/api/v1/starNote.(*NoteCategoryApi).UpdateUserNoteCategory\n	/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/starNote/note_category.go:288\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/flipped-aurora/gin-vue-admin/server/router/starNote.(*NoteCategoryRouter).InitNoteCategoryRouter.JWTAuthHeaderOnlyRest.func2\n	/Users/charles/Documents/notepad/gin-vue-admin/server/middleware/jwt.go:123\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.LoggerWithConfig.func1\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/logger.go:249\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/flipped-aurora/gin-vue-admin/server/initialize.Routers.GinRecovery.func7\n	/Users/charles/Documents/notepad/gin-vue-admin/server/middleware/error.go:78\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.(*Engine).handleHTTPRequest\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:633\ngithub.com/gin-gonic/gin.(*Engine).ServeHTTP\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:589\nnet/http.serverHandler.ServeHTTP\n	/Applications/ServBay/package/go/1.24/1.24.3/src/net/http/server.go:3301\nnet/http.(*conn).serve\n	/Applications/ServBay/package/go/1.24/1.24.3/src/net/http/server.go:2102 \n 最终调用方法:/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/starNote/note_category.go:288 (UpdateUserNoteCategory lines 273-313)\n----- 产生日志的方法代码如下 -----\nfunc (ncApi *NoteCategoryApi) UpdateUserNoteCategory(c *gin.Context) {\n	ctx := c.Request.Context()\n	userID := utils.GetUserID(c)\n\n	var req starNoteReq.UserNoteCategoryUpdateReq\n	if err := c.ShouldBindJSON(&req); err != nil {\n		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{\n			\"code\":    http.StatusBadRequest,\n			\"data\":    gin.H{},\n			\"message\": \"参数错误\",\n		})\n		return\n	}\n\n	if err := ncService.UpdateUserNoteCategory(ctx, userID, req.ID, req.Name, req.Color, req.Icon); err != nil {\n		global.GVA_LOG.Error(\"更新失败!\", zap.Error(err))\n		if errors.Is(err, gorm.ErrRecordNotFound) {\n			c.AbortWithStatusJSON(http.StatusNotFound, gin.H{\n				\"code\":    http.StatusNotFound,\n				\"data\":    gin.H{},\n				\"message\": \"分类不存在\",\n			})\n			return\n		}\n		if err.Error() == \"system category not allowed\" {\n			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{\n				\"code\":    http.StatusForbidden,\n				\"data\":    gin.H{},\n				\"message\": \"系统分类不可修改\",\n			})\n			return\n		}\n		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{\n			\"code\":    http.StatusInternalServerError,\n			\"data\":    gin.H{},\n			\"message\": \"服务器内部错误\",\n		})\n		return\n	}\n	response.OkWithMessage(\"更新成功\", c)\n}', 'error', NULL, '未处理');
INSERT INTO `sys_error` (`id`, `created_at`, `updated_at`, `deleted_at`, `form`, `info`, `level`, `solution`, `status`) VALUES (150, '2026-04-07 10:49:05.218', '2026-04-07 10:49:05.218', NULL, '后端', '登陆失败! 用户名不存在或者密码错误! | 错误: 密码错误 \n 源文件:/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/system/sys_user.go:68 \n 调用栈：github.com/flipped-aurora/gin-vue-admin/server/api/v1/system.(*BaseApi).Login\n	/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/system/sys_user.go:68\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.LoggerWithConfig.func1\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/logger.go:249\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/flipped-aurora/gin-vue-admin/server/initialize.Routers.GinRecovery.func7\n	/Users/charles/Documents/notepad/gin-vue-admin/server/middleware/error.go:78\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.(*Engine).handleHTTPRequest\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:633\ngithub.com/gin-gonic/gin.(*Engine).ServeHTTP\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:589\nnet/http.serverHandler.ServeHTTP\n	/Applications/ServBay/package/go/1.24/1.24.3/src/net/http/server.go:3301\nnet/http.(*conn).serve\n	/Applications/ServBay/package/go/1.24/1.24.3/src/net/http/server.go:2102 \n 最终调用方法:/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/system/sys_user.go:68 (Login lines 27-99)\n----- 产生日志的方法代码如下 -----\nfunc (b *BaseApi) Login(c *gin.Context) {\n	var l systemReq.Login\n	err := c.ShouldBindJSON(&l)\n	if err != nil {\n		response.FailWithMessage(err.Error(), c)\n		return\n	}\n	err = utils.Verify(l, utils.LoginVerify)\n	if err != nil {\n		response.FailWithMessage(err.Error(), c)\n		return\n	}\n\n	key := c.ClientIP()\n	// 判断验证码是否开启\n	openCaptcha := global.GVA_CONFIG.Captcha.OpenCaptcha               // 是否开启防爆次数\n	openCaptchaTimeOut := global.GVA_CONFIG.Captcha.OpenCaptchaTimeOut // 缓存超时时间\n	v, ok := global.BlackCache.Get(key)\n	if !ok {\n		global.BlackCache.Set(key, 1, time.Second*time.Duration(openCaptchaTimeOut))\n	}\n\n	var oc bool = openCaptcha == 0 || openCaptcha < interfaceToInt(v)\n	if oc && (l.Captcha == \"\" || l.CaptchaId == \"\" || !store.Verify(l.CaptchaId, l.Captcha, true)) {\n		// 验证码次数+1\n		global.BlackCache.Increment(key, 1)\n		response.FailWithMessage(\"验证码错误\", c)\n		// 记录登录失败日志\n		loginLogService.CreateLoginLog(system.SysLoginLog{\n			Username:     l.Username,\n			Ip:           c.ClientIP(),\n			Agent:        c.Request.UserAgent(),\n			Status:       false,\n			ErrorMessage: \"验证码错误\",\n		})\n		return\n	}\n\n	u := &system.SysUser{Username: l.Username, Password: l.Password}\n	user, err := userService.Login(u)\n	if err != nil {\n		global.GVA_LOG.Error(\"登陆失败! 用户名不存在或者密码错误!\", zap.Error(err))\n		// 验证码次数+1\n		global.BlackCache.Increment(key, 1)\n		response.FailWithMessage(\"用户名不存在或者密码错误\", c)\n		// 记录登录失败日志\n		loginLogService.CreateLoginLog(system.SysLoginLog{\n			Username:     l.Username,\n			Ip:           c.ClientIP(),\n			Agent:        c.Request.UserAgent(),\n			Status:       false,\n			ErrorMessage: \"用户名不存在或者密码错误\",\n		})\n		return\n	}\n	if user.Enable != 1 {\n		global.GVA_LOG.Error(\"登陆失败! 用户被禁止登录!\")\n		// 验证码次数+1\n		global.BlackCache.Increment(key, 1)\n		response.FailWithMessage(\"用户被禁止登录\", c)\n		// 记录登录失败日志\n		loginLogService.CreateLoginLog(system.SysLoginLog{\n			Username:     l.Username,\n			Ip:           c.ClientIP(),\n			Agent:        c.Request.UserAgent(),\n			Status:       false,\n			ErrorMessage: \"用户被禁止登录\",\n			UserID:       user.ID,\n		})\n		return\n	}\n	b.TokenNext(c, *user)\n}', 'error', NULL, '未处理');
