d/gin-vue-admin/server/api/v1/starNote/note_category.go:348 (DeleteUserNoteCategory lines 324-373)\n----- 产生日志的方法代码如下 -----\nfunc (ncApi *NoteCategoryApi) DeleteUserNoteCategory(c *gin.Context) {\n	ctx := c.Request.Context()\n	userID := utils.GetUserID(c)\n	// 这里沿用用户端星颜色的 query 参数风格\n	idStr := c.Query(\"id\")\n	if idStr == \"\" {\n		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{\n			\"code\":    http.StatusBadRequest,\n			\"data\":    gin.H{},\n			\"message\": \"参数错误\",\n		})\n		return\n	}\n	id64, err := strconv.ParseUint(idStr, 10, 64)\n	if err != nil {\n		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{\n			\"code\":    http.StatusBadRequest,\n			\"data\":    gin.H{},\n			\"message\": \"参数错误\",\n		})\n		return\n	}\n\n	if err := ncService.DeleteUserNoteCategory(ctx, userID, uint(id64)); err != nil {\n		global.GVA_LOG.Error(\"删除失败!\", zap.Error(err))\n		if errors.Is(err, gorm.ErrRecordNotFound) {\n			c.AbortWithStatusJSON(http.StatusNotFound, gin.H{\n				\"code\":    http.StatusNotFound,\n				\"data\":    gin.H{},\n				\"message\": \"分类不存在\",\n			})\n			return\n		}\n		if err.Error() == \"system category not allowed\" {\n			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{\n				\"code\":    http.StatusForbidden,\n				\"data\":    gin.H{},\n				\"message\": \"系统分类不可删除\",\n			})\n			return\n		}\n		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{\n			\"code\":    http.StatusInternalServerError,\n			\"data\":    gin.H{},\n			\"message\": \"服务器内部错误\",\n		})\n		return\n	}\n	response.OkWithMessage(\"删除成功\", c)\n}', 'error', NULL, '未处理');
