INSERT INTO `sys_error` (`id`, `created_at`, `updated_at`, `deleted_at`, `form`, `info`, `level`, `solution`, `status`) VALUES (208, '2026-04-22 16:09:59.093', '2026-04-22 16:09:59.093', NULL, '后端', '登录失败! | 错误: 535 Login fail. Account is abnormal, service is not open, password is incorrect, login frequency limited, or system is busy. More information at https://help.mail.qq.com/detail/108/1023 \n 源文件:/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/starNote/user_account.go:68 \n 调用栈：github.com/flipped-aurora/gin-vue-admin/server/api/v1/starNote.(*UserAccountApi).Login\n	/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/starNote/user_account.go:68\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.LoggerWithConfig.func1\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/logger.go:249\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/flipped-aurora/gin-vue-admin/server/initialize.Routers.GinRecovery.func7\n	/Users/charles/Documents/notepad/gin-vue-admin/server/middleware/error.go:78\ngithub.com/gin-gonic/gin.(*Context).Next\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.(*Engine).handleHTTPRequest\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:633\ngithub.com/gin-gonic/gin.(*Engine).ServeHTTP\n	/Users/charles/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:589\nnet/http.serverHandler.ServeHTTP\n	/Applications/ServBay/package/go/1.24/1.24.3/src/net/http/server.go:3301\nnet/http.(*conn).serve\n	/Applications/ServBay/package/go/1.24/1.24.3/src/net/http/server.go:2102 \n 最终调用方法:/Users/charles/Documents/notepad/gin-vue-admin/server/api/v1/starNote/user_account.go:68 (Login lines 55-139)\n----- 产生日志的方法代码如下 -----\nfunc (uaApi *UserAccountApi) Login(c *gin.Context) {\n	ctx := c.Request.Context()\n	var req starNoteReq.UserAccountLogin\n	if err := c.ShouldBindJSON(&req); err != nil {\n		c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{\n			\"code\":    http.StatusBadRequest,\n			\"data\":    gin.H{},\n			\"message\": \"参数错误\",\n		})\n		return\n	}\n	ua, needEmailVerify, challengeID, verifyCode, err := uaService.LoginWithDevice(ctx, req)\n	if err != nil {\n		global.GVA_LOG.Error(\"登录失败!\", zap.Error(err))\n		msg := \"登录失败\"\n		switch err.Error() {\n		case \"record not found\":\n			msg = \"用户不存在\"\n		case \"password incorrect\":\n			msg = \"密码错误\"\n		case \"password required\":\n			msg = \"请输入密码\"\n		case \"username or emailPhone required\":\n			msg = \"请输入用户名或邮箱\"\n		case \"deviceId required\":\n			msg = \"缺少设备标识\"\n		case \"password not set\":\n			msg = \"该账号未设置密码\"\n		case \"db not init\":\n			msg = \"服务器内部错误\"\n		}\n		c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{\n			\"code\":    http.StatusUnauthorized,\n			\"data\":    gin.H{},\n			\"message\": msg,\n		})\n		return\n	}\n	if needEmailVerify {\n		message := \"需要邮箱验证\"\n		if !global.GVA_CONFIG.Email.Pattern && verifyCode != \"\" {\n			message = verifyCode\n		}\n		c.JSON(http.StatusOK, gin.H{\n			\"code\": http.StatusOK,\n			\"data\": gin.H{\n				\"needEmailVerify\": true,\n				\"challengeId\":     challengeID,\n			},\n			\"message\": message,\n		})\n		return\n	}\n\n	token, claims, err := utils.LoginToken(&ua)\n	if err != nil {\n		global.GVA_LOG.Error(\"获取token失败!\", zap.Error(err))\n		c.AbortWithStatusJSON(http.StatusInternalServerError, gin.H{\n			\"code\":    http.StatusInternalServerError,\n			\"data\":    gin.H{},\n			\"message\": \"服务器内部错误\",\n		})\n		return\n	}\n	utils.SetToken(c, token, int(claims.RegisteredClaims.ExpiresAt.Unix()-time.Now().Unix()))\n	stService.TriggerOnLoginSuccessAsync(ctx, ua.ID)\n	c.JSON(http.StatusOK, gin.H{\n		\"code\": http.StatusOK,\n		\"data\": gin.H{\n			\"user\": gin.H{\n				\"id\":         ua.ID,\n				\"username\":   ua.Username,\n				\"emailPhone\": ua.EmailPhone,\n				\"nickname\":   ua.Nickname,\n				\"avatar\":     ua.Avatar,\n				\"gender\":     ua.Gender,\n				\"address\":    ua.Address,\n				\"signature\":  ua.Signature,\n			},\n			\"token\":     token,\n			\"expiresAt\": claims.RegisteredClaims.ExpiresAt.Unix() * 1000,\n		},\n		\"message\": \"登录成功\",\n	})\n}', 'error', NULL, '未处理');
