INSERT INTO `sys_error` (`id`, `created_at`, `updated_at`, `deleted_at`, `form`, `info`, `level`, `solution`, `status`) VALUES (226, '2026-05-07 09:12:57.448', '2026-05-07 09:12:57.448', NULL, '后端', 'AI聊天失败! | 错误: Invalid API Key \n 源文件:/app/api/v1/system/blog_config.go:276 \n 调用栈：github.com/flipped-aurora/gin-vue-admin/server/api/v1/system.(*UserBlog_configApi).PublicAIChat\n	/app/api/v1/system/blog_config.go:276\ngithub.com/gin-gonic/gin.(*Context).Next\n	/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.LoggerWithConfig.func1\n	/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/logger.go:249\ngithub.com/gin-gonic/gin.(*Context).Next\n	/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/flipped-aurora/gin-vue-admin/server/initialize.Routers.GinRecovery.func7\n	/app/middleware/error.go:78\ngithub.com/gin-gonic/gin.(*Context).Next\n	/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/context.go:185\ngithub.com/gin-gonic/gin.(*Engine).handleHTTPRequest\n	/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:633\ngithub.com/gin-gonic/gin.(*Engine).ServeHTTP\n	/go/pkg/mod/github.com/gin-gonic/gin@v1.10.0/gin.go:589\nnet/http.serverHandler.ServeHTTP\n	/usr/local/go/src/net/http/server.go:3301\nnet/http.(*conn).serve\n	/usr/local/go/src/net/http/server.go:2102 \n 最终调用方法:/app/api/v1/system/blog_config.go:276 (PublicAIChat lines 251-282)\n----- 产生日志的方法代码如下 -----\nfunc (bcApi *UserBlog_configApi) PublicAIChat(c *gin.Context) {\n	ctx := c.Request.Context()\n\n	var req systemReq.PublicChatReq\n	if err := c.ShouldBindJSON(&req); err != nil {\n		response.FailWithMessage(\"参数错误:\"+err.Error(), c)\n		return\n	}\n\n	// 获取个人资料，构建系统提示\n	bc, _ := bcService.GetUserBlog_configPublic(ctx)\n	systemPrompt := buildChatSystemPrompt(bc)\n\n	// 组装消息：系统提示放首位，之后是用户对话\n	messages := make([]map[string]string, 0, len(req.Messages)+1)\n	messages = append(messages, map[string]string{\"role\": \"system\", \"content\": systemPrompt})\n	for _, m := range req.Messages {\n		if strings.TrimSpace(m.Role) == \"\" || strings.TrimSpace(m.Content) == \"\" {\n			continue\n		}\n		messages = append(messages, map[string]string{\"role\": m.Role, \"content\": m.Content})\n	}\n\n	reply, err := aiProviderService.PublicChatWithAI(ctx, messages)\n	if err != nil {\n		global.GVA_LOG.Error(\"AI聊天失败!\", zap.Error(err))\n		response.FailWithMessage(err.Error(), c)\n		return\n	}\n\n	response.OkWithDetailed(gin.H{\"reply\": reply}, \"获取成功\", c)\n}', 'error', NULL, '未处理');
INSERT INTO `sys_error` (`id`, `created_at`, `updated_at`, `deleted_at`, `form`, `info`, `level`, `solution`, `status`) VALUES (227, '2026-05-07 09:13:09.810', '2026-05-07 09:13:09.810', NULL, '后端', 'record login failed | 错误: context canceled \n 源文件:/app/service/starNote/tag_auto_assign.go:37 \n 调用栈：github.com/flipped-aurora/gin-vue-admin/server/service/starNote.(*StarTagService).TriggerOnLoginSuccessAsync.func1\n	/app/service/starNote/tag_auto_assign.go:37\ngithub.com/flipped-aurora/gin-vue-admin/server/service/starNote.(*StarTagService).runAsync.func1\n	/app/service/starNote/tag_auto_assign.go:75 \n 最终调用方法:/app/service/starNote/tag_auto_assign.go:37 (TriggerOnLoginSuccessAsync lines 34-43)\n----- 产生日志的方法代码如下 -----\nfunc (stService *StarTagService) TriggerOnLoginSuccessAsync(ctx context.Context, userID uint) {\n	stService.runAsync(ctx, userID, func(runCtx context.Context) {\n		if err := stService.recordLogin(runCtx, userID, time.Now()); err != nil {\n			global.GVA_LOG.Error(\"record login failed\", zap.Uint(\"userID\", userID), zap.Error(err))\n		}\n		if err := stService.EvaluateAndAssignImplementedTags(runCtx, userID); err != nil {\n			global.GVA_LOG.Error(\"evaluate tags after login failed\", zap.Uint(\"userID\", userID), zap.Error(err))\n		}\n	})\n}', 'error', NULL, '未处理');
