-- Table structure for daily_events
-- ----------------------------
DROP TABLE IF EXISTS `daily_events`;
CREATE TABLE `daily_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
