  `type` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '分类 (0:诞辰, 1:祭日, 2:正面的, 3:负面的)',
  `weight` bigint DEFAULT NULL COMMENT '权重 (用于当一天有 20 个事件时，决定谁排在最前面)',
  `cover_img` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '封面图 URL (符合数字媒体专业的审美要求)',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '简评',
  `quote` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '名言',
  PRIMARY KEY (`id`),
  KEY `idx_daily_events_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3920 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

