  `challenge_id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '登录挑战ID',
  `device_id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备ID',
  `attempt_count` bigint DEFAULT NULL COMMENT '尝试次数',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '用户ID',
  PRIMARY KEY (`id`),
  KEY `idx_user_email_codes_device_id` (`device_id`),
  KEY `idx_user_email_codes_deleted_at` (`deleted_at`),
  KEY `idx_user_email_codes_email` (`email`),
