  KEY `idx_user_email_codes_expires_at` (`expires_at`),
  KEY `idx_user_email_codes_challenge_id` (`challenge_id`),
  KEY `idx_user_email_codes_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

